T_KERNEL.patch:
diff --git a/src/RimMandrake/ExplosiveKnockback/Source/RM_KnockbackMath.cs b/src/RimMandrake/ExplosiveKnockback/Source/RM_KnockbackMath.cs
index c4d5d6130c..633c1113cf 100644
--- a/src/RimMandrake/ExplosiveKnockback/Source/RM_KnockbackMath.cs
+++ b/src/RimMandrake/ExplosiveKnockback/Source/RM_KnockbackMath.cs
@@ -192,7 +192,7 @@ namespace RimMandrake.ExplosiveKnockback
         public static float MassScale(float mass, KbSettings s)
         {
             float m = Math.Max(mass, 1f);
-            float v = (float)Math.Sqrt(s.refMass / m);
+            float v = (float)Math.Sqrt(m / s.refMass);
             return v < 0.25f ? 0.25f : (v > 2f ? 2f : v);
         }

